  ["AI Insights","/ai-insights",WandSparkles,["ADMIN","TEAM_LEAD","EMPLOYEE"],"INTELLIGENCE"],
  ["AI Automations","/automations",RefreshCw,["ADMIN","TEAM_LEAD"],"INTELLIGENCE"],
  ["Reports","/reports",BarChart3,["ADMIN","TEAM_LEAD"],"INTELLIGENCE"],
  ["AI Activity","/ai-activity",ClipboardList,["ADMIN","TEAM_LEAD"],"INTELLIGENCE"],
  ["Follow-ups","/followups",CalendarClock,["ADMIN","TEAM_LEAD","EMPLOYEE"],"WORKSPACE"]
