function ReportsPage({ department = "ALL" }) {
  const [summary, setSummary] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get("/reports/summary", { params: { department: department === "ALL" ? undefined : department } })
      .then(response => setSummary(response.data.data))
      .catch(err => setError(err.response?.data?.message || "Could not load reports."))
      .finally(() => setLoading(false));
  }, [department]);

  function downloadCsv() {
    if (!summary) return;
    const rows = [
      ["Metric", "Value"],
      ["Department", department === "ALL" ? "All Departments" : departmentName(department)],
      ["Active customers", summary.customers],
      ["Inbound leads", summary.inboundLeads],
      ["Open pipeline (INR)", summary.pipelineValue],
      ["Won revenue (INR)", summary.wonRevenue],
      ["Open tickets", summary.openTickets],
      ["Active staff", summary.employees],
      ["Open tasks", summary.openTasks]
    ];
    const csv = rows.map(row => row.map(value => `"${String(value ?? "").replaceAll('"', '""')}"`).join(",")).join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = "bitso-crm-executive-report.csv";
    link.click();
    URL.revokeObjectURL(url);
  }

  return <div className="records-page">
    <div className="page-heading"><div><h1>Executive Reports</h1><p>Live CRM totals and department operating metrics.</p></div><button className="primary" onClick={downloadCsv} disabled={!summary}><FileDown size={16}/> Export CSV</button></div>
    {error && <div className="notice error-notice">{error}</div>}
    {loading ? <div className="table-empty">Loading report…</div> : summary && <>
      <div className="executive-kpis report-kpis">{[["Active customers", summary.customers], ["Inbound leads", summary.inboundLeads], ["Open pipeline", `₹${Number(summary.pipelineValue).toLocaleString("en-IN")}`], ["Won revenue", `₹${Number(summary.wonRevenue).toLocaleString("en-IN")}`], ["Open tickets", summary.openTickets], ["Active staff", summary.employees]].map(([label, value]) => <article className="executive-kpi" key={label}><div className="executive-kpi-heading"><span>{label}</span></div><div className="executive-kpi-value">{value}</div></article>)}</div>
      <div className="executive-panel report-matrix"><div className="executive-section-heading"><div><h2>Department operations</h2><p>Customer accounts, lead volume, pipeline value and tickets.</p></div></div><div className="table-wrap"><table><thead><tr><th>Department</th><th>Staff</th><th>Customers</th><th>Leads</th><th>Pipeline (₹)</th><th>Tickets</th></tr></thead><tbody>{summary.departmentMatrix.map(row => <tr key={row.department}><td>{departmentName(row.department)}</td><td>{row.staff}</td><td>{row.customers}</td><td>{row.leads}</td><td>₹{Number(row.pipelineValue).toLocaleString("en-IN")}</td><td>{row.tickets}</td></tr>)}</tbody></table></div></div>
    </>}
  </div>;
}
function IntelligencePage({ mode, department = "ALL" }) {
  const [summary, setSummary] = useState(null);
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState("");
  const [error, setError] = useState("");

  useEffect(() => {
    api.get("/reports/summary", { params: { department: department === "ALL" ? undefined : department } })
      .then(response => setSummary(response.data.data))
      .catch(err => setError(err.response?.data?.message || "Could not load CRM context."));
  }, [department]);

  const insightItems = summary ? [
    [summary.openTickets > 0 ? "attention" : "healthy", "Service queue", summary.openTickets > 0 ? `${summary.openTickets} ticket(s) are open and need follow-up.` : "There are no open service tickets."],
    [summary.inboundLeads > 0 ? "opportunity" : "neutral", "Lead pipeline", `${summary.inboundLeads} active lead(s); total lead records ${summary.leads}.`],
    [summary.openTasks > 0 ? "attention" : "healthy", "Team delivery", `${summary.openTasks} task(s) remain open across this scope.`],
    ["neutral", "Revenue position", `Open pipeline ₹${Number(summary.pipelineValue).toLocaleString("en-IN")}; won revenue ₹${Number(summary.wonRevenue).toLocaleString("en-IN")}.`]
  ] : [];

  function ask(event) {
    event.preventDefault();
    if (!summary || !question.trim()) return;
    const text = question.toLowerCase();
    if (text.includes("ticket") || text.includes("support")) setAnswer(`There are ${summary.openTickets} open of ${summary.tickets} total service tickets in this CRM scope.`);
    else if (text.includes("lead")) setAnswer(`There are ${summary.inboundLeads} active leads from ${summary.leads} total lead records.`);
    else if (text.includes("revenue") || text.includes("pipeline") || text.includes("deal")) setAnswer(`Open deal pipeline is ₹${Number(summary.pipelineValue).toLocaleString("en-IN")}; won revenue is ₹${Number(summary.wonRevenue).toLocaleString("en-IN")}.`);
    else if (text.includes("task")) setAnswer(`${summary.openTasks} tasks are not marked done.`);
    else setAnswer(`Current scope: ${summary.customers} customers, ${summary.inboundLeads} active leads, ${summary.openTasks} open tasks, and ${summary.openTickets} open tickets. Open pipeline ₹${Number(summary.pipelineValue).toLocaleString("en-IN")}.`);
  }

  if (mode === "copilot") return <div className="intelligence-page"><div className="page-heading"><div><div className="eyebrow">GROUNDED IN LIVE CRM DATA</div><h1>CRM Copilot</h1><p>Ask a question about current leads, tickets, tasks or pipeline totals.</p></div><span className="scope-badge">{department === "ALL" ? "All Departments" : departmentName(department)}</span></div>{error && <div className="notice error-notice">{error}</div>}<section className="copilot-panel"><div className="copilot-panel-head"><span><Bot size={19}/></span><div><h2>Ask your CRM</h2><p>Answers use current CRM metrics only; no external AI provider is connected.</p></div></div><form onSubmit={ask}><label htmlFor="copilot-question">Your question</label><textarea id="copilot-question" value={question} onChange={event => setQuestion(event.target.value)} placeholder="How many open tickets need attention?" rows="3"/><button className="copilot-launch" disabled={!summary}><Sparkles size={16}/> Ask Copilot</button></form>{answer && <div className="copilot-answer"><span className="briefing-icon"><Sparkles size={16}/></span><p>{answer}</p></div>}</section><div className="copilot-suggestions">{["How many open leads are there?", "What is our open pipeline?", "How many tickets need attention?"].map(item => <button key={item} onClick={() => setQuestion(item)}>{item}</button>)}</div></div>;

  if (mode === "automations") return <div className="intelligence-page"><div className="page-heading"><div><div className="eyebrow">WORKFLOW STATUS</div><h1>AI Automations</h1><p>Available operational workflows in this CRM.</p></div><span className="scope-badge">PROVIDER NOT CONNECTED</span></div><div className="automation-grid"><article className="automation-card"><span><CalendarClock size={19}/></span><h2>Follow-up reminders</h2><p>Track due dates and completion status from the Follow-ups workspace.</p><NavLink to="/followups">Open follow-ups <ArrowRight size={14}/></NavLink></article><article className="automation-card"><span><Headphones size={19}/></span><h2>Ticket triage</h2><p>Set ticket priority and status manually; automated classification is not enabled.</p><NavLink to="/tickets">Open tickets <ArrowRight size={14}/></NavLink></article><article className="automation-card"><span><Users size={19}/></span><h2>Lead qualification</h2><p>Update lead stages and estimated value in the lead pipeline.</p><NavLink to="/leads">Open leads <ArrowRight size={14}/></NavLink></article></div><div className="notice">Automated AI actions are disabled until an approved AI provider and rules are configured.</div></div>;

  return <div className="intelligence-page"><div className="page-heading"><div><div className="eyebrow">DATA-GROUNDED ANALYSIS</div><h1>Executive Insights</h1><p>Rule-based signals calculated from live CRM records.</p></div><span className="scope-badge">{department === "ALL" ? "All Departments" : departmentName(department)}</span></div>{error && <div className="notice error-notice">{error}</div>}<div className="insight-grid">{insightItems.map(([tone, title, text]) => <article className={`insight-card ${tone}`} key={title}><span><Sparkles size={17}/></span><div><h2>{title}</h2><p>{text}</p></div></article>)}</div><div className="notice">These are deterministic CRM summaries, not generated by an external AI model.</div></div>;
}
function Dashboard(){
 const [summary,setSummary]=useState(null);const [error,setError]=useState("");const [refreshing,setRefreshing]=useState(false);
 async function loadSummary(){setRefreshing(true);try{const {data}=await api.get("/reports/summary");setSummary(data.data);setError("");}catch(err){setError(err.response?.data?.message||"Could not load dashboard summary.");}finally{setRefreshing(false);}}
 useEffect(()=>{loadSummary();window.addEventListener("crm:records-changed",loadSummary);return()=>window.removeEventListener("crm:records-changed",loadSummary);},[]);
 const {user}=useAuth();
 const cards=[["Total leads",summary?.leads??"—",Users],["Clients",summary?.clients??"—",Building2],["Active employees",summary?.employees??"—",UserRound],["Projects",summary?.projects??"—",FolderKanban],["Open tasks",summary?.tasks??"—",CheckSquare],["Won revenue",summary?`₹${Number(summary.wonRevenue).toLocaleString("en-IN")}`:"—",IndianRupee]];
 return <><div className="welcome"><div><div className="eyebrow">OVERVIEW</div><h1>Good day, {user.name.split(" ")[0]}.</h1><p>Here’s what’s happening across Bitso Innovations.</p></div><div className="welcome-actions"><div className="welcome-chip"><span className="live-dot"/> Workspace active</div><button className="refresh-btn" onClick={loadSummary} disabled={refreshing} title="Refresh dashboard" aria-label="Refresh dashboard"><RefreshCw size={16} className={refreshing?"spinning":""}/><span>Refresh</span></button></div></div>{error&&<div className="notice error-notice">{error}</div>}<div className="stats-grid">{cards.map(([label,value,Icon])=><div className="stat-card" key={label}><div className="stat-top"><span>{label}</span><div className="stat-icon"><Icon size={18}/></div></div><strong>{value}</strong><small>{user.role==="EMPLOYEE"&&["Total leads","Projects","Open tasks","Won revenue"].includes(label)?"Assigned to you":"Current records"}</small></div>)}</div><div className="dashboard-grid"><div className="panel"><div className="panel-head"><div><h3>Lead pipeline</h3><p>Current lead distribution</p></div><span className="panel-tag">STATUS</span></div>{summary?.leadBreakdown?.length?<div className="breakdown">{summary.leadBreakdown.map(x=><div className="break-row" key={x.status}><span>{x.status.replace("_"," ")}</span><div className="bar"><i style={{width:`${Math.max(4,x._count._all/Math.max(1,summary.leads)*100)}%`}}/></div><b>{x._count._all}</b></div>)}</div>:<Empty text="Lead status insights will appear here once records are added."/>}</div><div className="panel"><div className="panel-head"><div><h3>Task progress</h3><p>{user.role==="EMPLOYEE"?"Your assigned work":"Team delivery snapshot"}</p></div><span className="panel-tag">TASKS</span></div>{summary?.taskBreakdown?.length?<div className="breakdown">{summary.taskBreakdown.map(x=><div className="break-row" key={x.status}><span>{x.status.replace("_"," ")}</span><div className="bar"><i style={{width:`${Math.max(4,x._count._all/Math.max(1,summary.tasks)*100)}%`}}/></div><b>{x._count._all}</b></div>)}</div>:<Empty text="Task progress will appear here."/>}</div></div><div className="tip"><Bell size={18}/><div><b>Keep your CRM up to date</b><span>Add new leads, assign follow-ups and update task statuses to keep your team aligned.</span></div></div></>;
}
function Empty({text}){return <div className="empty"><div className="empty-icon"><FolderKanban size={20}/></div><p>{text}</p></div>}
const fields={
 leads:[["name","Lead name","text",true],["email","Email","email"],["phone","Phone","text"],["company","Company","text"],["source","Source","text"],["status","Status","select",false,["NEW","CONTACTED","QUALIFIED","PROPOSAL","WON","LOST"]],["value","Estimated value (₹)","number"],["notes","Notes","textarea"]],
 clients:[["name","Client name","text",true],["email","Email","email"],["phone","Phone","text"],["company","Company","text"],["address","Address","text"],["notes","Notes","textarea"]],
 projects:[["name","Project name","text",true],["description","Description","textarea"],["status","Status","select",false,["PLANNING","ACTIVE","ON_HOLD","COMPLETED"]],["budget","Budget (₹)","number"],["startDate","Start date","date"],["dueDate","Due date","date"]],
 tasks:[["title","Task title","text",true],["description","Description","textarea"],["status","Status","select",false,["TODO","IN_PROGRESS","BLOCKED","DONE"]],["priority","Priority","select",false,["LOW","MEDIUM","HIGH","URGENT"]],["dueDate","Due date","date"],["assigneeId","Assign employee ID","text"],["projectId","Project ID","text"]],
 sales:[["title","Sale title","text",true],["amount","Amount (₹)","number",true],["status","Status","select",false,["PENDING","WON","LOST"]],["saleDate","Sale date","date"],["clientName","Client name","text"]],
 followups:[["title","Follow-up title","text",true],["details","Details","textarea"],["dueAt","Due date & time","datetime-local",true],["leadId","Lead ID","text"],["completed","Completed","select",false,["false","true"]]],
 tickets:[["title","Ticket subject","text",true],["customerName","Customer name","text"],["customerEmail","Customer email","email"],["description","Description","textarea"],["status","Status","select",false,["OPEN","IN_PROGRESS","WAITING","RESOLVED","CLOSED"]],["priority","Priority","select",false,["LOW","MEDIUM","HIGH","URGENT"]]]
};
const columns={
 leads:[["name","Lead"],["company","Company"],["status","Status"],["value","Value"],["ownerId","Owner ID"]],
 clients:[["name","Client"],["company","Company"],["email","Email"],["phone","Phone"]],
 employees:[["name","Employee"],["email","Email"],["phone","Contact"],["department","Department"],["role","Role"],["active","Active"]],
 projects:[["name","Project"],["status","Status"],["budget","Budget"],["dueDate","Due date"]],
 tasks:[["title","Task"],["status","Status"],["priority","Priority"],["dueDate","Due date"],["assigneeId","Assignee"]],
 sales:[["title","Sale"],["amount","Amount"],["status","Status"],["clientName","Client"]],
 followups:[["title","Follow-up"],["dueAt","Due"],["completed","Completed"],["leadId","Lead ID"]],
 tickets:[["title","Ticket"],["customerName","Customer"],["status","Status"],["priority","Priority"],["department","Department"]],
 contacts:[["name","Contact"],["company","Company"],["email","Email"],["phone","Phone"]]
};
function ResourcePage({name,path,department="ALL"}){
 const {user}=useAuth();const [rows,setRows]=useState([]);const [loading,setLoading]=useState(true);const [search,setSearch]=useState("");const [modal,setModal]=useState(false);const [editing,setEditing]=useState(null);const [error,setError]=useState("");const [employees,setEmployees]=useState([]);
 const isEmployees=path==="employees";
 const load=()=>{setLoading(true);api.get(`/${path}`,{params:{search,department:department==="ALL"?undefined:department}}).then(r=>setRows(r.data.data||[])).catch(e=>setError(e.response?.data?.message||"Could not load records.")).finally(()=>setLoading(false));};
 useEffect(()=>{load();if(["tasks","leads","projects","sales","followups","tickets"].includes(path))api.get("/employees",{params:{department:department==="ALL"?undefined:department}}).then(r=>setEmployees(r.data.data||[])).catch(()=>{});},[path,search,department]);
 const canDelete=user.role!=="EMPLOYEE";const canAdd=!(isEmployees&&user.role!=="ADMIN");
 const startEdit=(row)=>{setEditing(row);setModal(true);};const startAdd=()=>{setEditing(null);setModal(true);};
 async function remove(id){if(!confirm("Delete this record permanently?"))return;try{await api.delete(`/${path}/${id}`);load();window.dispatchEvent(new Event("crm:records-changed"));}catch(e){setError(e.response?.data?.message||"Delete failed.");}}
 async function save(payload){try{if(isEmployees&&editing){await api.patch(`/employees/${editing.id}`,payload);}else if(isEmployees){await api.post("/employees",payload);}else if(editing){await api.patch(`/${path}/${editing.id}`,payload);}else{payload.department=department==="ALL"?user.department:department;await api.post(`/${path}`,payload);}setModal(false);load();window.dispatchEvent(new Event("crm:records-changed"));}catch(e){throw new Error(e.response?.data?.message||"Could not save record.");}}
 return <><div className="page-heading"><div><h1>{name}</h1><p>Manage and track your {name.toLowerCase()} in one place.</p></div>{canAdd&&<button className="primary" onClick={startAdd}><Plus size={17}/> Add {isEmployees?"employee":name.slice(0,-1)}</button>}</div><div className="toolbar"><div className="searchbox"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={`Search ${name.toLowerCase()}…`}/></div><span className="record-count">{rows.length} records</span></div>{error&&<div className="notice error-notice">{error}</div>}<div className="table-wrap"><table><thead><tr>{(columns[path]||[]).map(c=><th key={c[0]}>{c[1]}</th>)}<th>Actions</th></tr></thead><tbody>{loading?<tr><td colSpan="8" className="table-empty">Loading records…</td></tr>:rows.length===0?<tr><td colSpan="8" className="table-empty">No records found. Add your first record to get started.</td></tr>:rows.map(row=><tr key={row.id}>{(columns[path]||[]).map(([key])=><td key={key}>{key==="status"||key==="priority"||key==="role"?<span className={`pill ${String(row[key]).toLowerCase()}`}>{String(row[key]||"—").replace("_"," ")}</span>:key==="department"?<span className="pill department-pill">{departmentName(row[key])}</span>:key==="amount"||key==="budget"||key==="value"?`₹${Number(row[key]||0).toLocaleString("en-IN")}`:key==="active"||key==="completed"?String(row[key]):key.toLowerCase().includes("date")&&row[key]?new Date(row[key]).toLocaleDateString("en-IN"):row[key]||"—"}</td>)}<td><div className="actions"><button onClick={()=>startEdit(row)} className="link-btn">Edit</button>{canDelete&&<button onClick={()=>remove(row.id)} className="link-btn danger-link">Delete</button>}</div></td></tr>)}</tbody></table></div>{modal&&<RecordModal name={name} path={path} editing={editing} employees={employees} onClose={()=>setModal(false)} onSave={save}/>}</>;
}
function RecordModal({name,path,editing,employees,onClose,onSave}){
 const isEmployees=path==="employees";const employeeConfig=[["name","Full name","text",true],["email","Work email","email",true],["phone","Phone / contact","tel"],["department","Department / domain","select",true,departmentOptions.map(([value])=>value)],["role","Role","select",true,["ADMIN","TEAM_LEAD","EMPLOYEE"]],...(editing?[["active","Account status","select",true,["true","false"]]]:[["password","Temporary password","password",true]])];const config=isEmployees?employeeConfig:fields[path]||[];
 const [values,setValues]=useState(()=>{const v={};config.forEach(([k])=>{v[k]=editing?.[k]??(k==="status"?(path==="leads"?"NEW":path==="tasks"?"TODO":path==="tickets"?"OPEN":"PLANNING"):k==="priority"?"MEDIUM":k==="completed"||k==="active"?String(k==="active"?true:false):"");if(k.toLowerCase().includes("date")&&v[k])v[k]=String(v[k]).slice(0,k==="dueAt"?16:10);});return v;});
 const [error,setError]=useState("");const [busy,setBusy]=useState(false);
 function change(k,v){setValues(old=>({...old,[k]:v}));}
 async function submit(e){e.preventDefault();setBusy(true);setError("");const payload={...values};for(const k of ["value","budget","amount"])if(payload[k]!==undefined&&payload[k]!=="")payload[k]=Number(payload[k]);for(const k of ["startDate","dueDate","saleDate","dueAt"])if(payload[k])payload[k]=new Date(payload[k]).toISOString();for(const k of ["completed","active"])if(payload[k]!==undefined)payload[k]=payload[k]==="true";for(const k of Object.keys(payload))if(payload[k]==="")delete payload[k];try{await onSave(payload);}catch(e){setError(e.message);}finally{setBusy(false);}}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal"><div className="modal-head"><div><span className="eyebrow">{editing?"UPDATE RECORD":"NEW RECORD"}</span><h2>{editing?"Edit": "Add"} {isEmployees?"employee":name.slice(0,-1)}</h2></div><button className="icon-btn" onClick={onClose}><X/></button></div><form onSubmit={submit}><div className="form-grid">{config.map(([key,label,type,required,options])=><div className={`field ${type==="textarea"?"span-2":""}`} key={key}><label>{label}{required?" *":""}</label>{type==="textarea"?<textarea rows="3" value={values[key]} onChange={e=>change(key,e.target.value)}/>:type==="select"?<select value={values[key]} onChange={e=>change(key,e.target.value)}><option value="" disabled>Select {label.toLowerCase()}</option>{options.map(o=><option key={o} value={o}>{key==="department"?departmentName(o):o.replace("_"," ")}</option>)}</select>:<input type={type} required={required} value={values[key]} onChange={e=>change(key,e.target.value)} min={type==="number"?"0":undefined}/>}</div>)}</div>{error&&<div className="error">{error}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy?"Saving…":"Save record"}</button></div></form></div></div>;
}
export default App;
